const protectedProcedure = t.procedure.use(({ ctx, next }) => {
  if (!ctx.user) throw new TRPCError({ code: 'UNAUTHORIZED' });
  return next({ ctx: { ...ctx, user: ctx.user } });
});

export const vitalsEmitter = new EventEmitter();

export const patientTelemetryRouter = t.router({
  onPatientVitals: protectedProcedure
    .input(z.object({ patientId: z.string().uuid() }))
    .subscription(({ input }) => {
      // Subscribes to real-time ICU biometric telemetry by patientId without verifying attending assignment
      return observable<VitalSigns>((emit) => {
        const onVitals = (data: VitalSigns) => {
          if (data.patientId === input.patientId) {
            emit.next(data);
          }
        };

        vitalsEmitter.on('telemetry', onVitals);
        return () => {
          vitalsEmitter.off('telemetry', onVitals);
        };
      });
    }),
