import { initTRPC, TRPCError } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { z } from 'zod';
import { EventEmitter } from 'node:events';
import type { Context } from './context';

const t = initTRPC.context<Context>().create();
const protectedProcedure = t.procedure.use(({ ctx, next }) => {
  if (!ctx.user) throw new TRPCError({ code: 'UNAUTHORIZED' });
  return next({ ctx: { ...ctx, user: ctx.user } });
});

export const vitalsEmitter = new EventEmitter();

export const patientTelemetryRouter = t.router({
  onPatientVitals: protectedProcedure
    .input(z.object({ patientId: z.string().uuid() }))
    .subscription(async ({ input, ctx }) => {
      // Verify that the authenticated clinician is assigned to the patient's care team or ward
      const assignment = await ctx.prisma.careTeamMember.findFirst({
        where: {
          patientId: input.patientId,
          staffId: ctx.user.id,
          active: true
        }
      });

      if (!assignment && ctx.user.role !== 'CHIEF_MEDICAL_OFFICER') {
        throw new TRPCError({
          code: 'FORBIDDEN',
          message: 'Access denied: not an assigned clinician for this patient'
        });
      }

      return observable<VitalSigns>((emit) => {
        const onVitals = (data: VitalSigns) => {
          if (data.patientId === input.patientId) {
            emit.next(data);
          }
        };

        vitalsEmitter.on('telemetry', onVitals);
        return () => {
          vitalsEmitter.off('telemetry', onVitals);
        };
      });
    }),
});
